/** Validated create-user request. */
export interface CreateUser {
  email: string;
  name: string;
  age: number;
}

/** Untrusted create-user input accepted by {@link validateCreateUser}. */
export interface CreateUserInput {
  email?: unknown;
  name?: unknown;
  age?: unknown;
}

/** Successful outcome of {@link validateCreateUser}. */
export interface ValidResult {
  ok: true;
  value: CreateUser;
}

/** Failed outcome of {@link validateCreateUser}. */
export interface InvalidResult {
  ok: false;
  errors: string[];
}

/** Outcome of {@link validateCreateUser}. */
export type ValidationResult = ValidResult | InvalidResult;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const MESSAGE_EMAIL_INVALID = "email must be a valid address";
const MESSAGE_NAME_REQUIRED = "name is required";
const MESSAGE_AGE_REQUIRED = "age is required";
const MESSAGE_AGE_INVALID = "age must be a non-negative integer";
const MESSAGE_BODY_INVALID = "request body must be a JSON object";

/**
 * Reports whether a value is a non-null, non-array object.
 *
 * @param value - Untrusted value.
